"use client";

import * as React from "react";
import { DayButton, DayPicker } from "react-day-picker";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";
import { buttonVariants } from "./button";
import { focusRing, primaryFinish, primaryFinishHover } from "./_shared";

/** Props for the Calendar, where every react-day-picker prop passes through. */
export type CalendarProps = React.ComponentProps<typeof DayPicker>;

const navButton = cn(
  buttonVariants({ variant: "secondary", size: "icon-sm" }),
  "size-8 aria-disabled:pointer-events-none aria-disabled:opacity-50",
);

const arrowIcons = {
  left: "iconoir:nav-arrow-left",
  right: "iconoir:nav-arrow-right",
  up: "iconoir:nav-arrow-up",
  down: "iconoir:nav-arrow-down",
} as const;

function CalendarChevron({
  orientation = "left",
  className,
}: {
  orientation?: keyof typeof arrowIcons;
  className?: string;
}) {
  return <Icon icon={arrowIcons[orientation]} aria-hidden="true" className={cn("size-4", className)} />;
}

// A chosen day, and each end of a range, takes the solid violet finish; the days between sit on a lilac band.
function CalendarDayButton({ className, modifiers, ...props }: React.ComponentProps<typeof DayButton>) {
  const filled = modifiers.selected && !modifiers.range_middle;

  return (
    <DayButton
      modifiers={modifiers}
      data-slot="calendar-day"
      className={cn(
        className,
        modifiers.outside && "text-muted-foreground",
        modifiers.today && !modifiers.selected && "font-medium inset-ring-1 inset-ring-input",
        modifiers.range_middle && "rounded-none bg-transparent hover:bg-transparent",
        filled && cn(primaryFinish, primaryFinishHover, "font-medium"),
        modifiers.disabled && "opacity-40",
      )}
      {...props}
    />
  );
}

/** Mallow Calendar: a month of 2.25rem round days where a chosen day is solid violet and a range runs along a lilac band. */
function Calendar({ className, classNames, showOutsideDays = true, components, ...props }: CalendarProps) {
  return (
    <DayPicker
      data-slot="calendar"
      showOutsideDays={showOutsideDays}
      className={cn("p-3", className)}
      classNames={{
        months: "relative flex flex-col gap-4 sm:flex-row",
        month: "flex flex-col gap-3",
        month_caption: "flex h-8 items-center justify-center",
        caption_label:
          "inline-flex items-center gap-1 text-sm font-medium text-foreground [&_svg]:size-3.5 [&_svg]:text-muted-foreground",
        dropdowns: "flex items-center gap-2",
        dropdown_root:
          "relative inline-flex items-center rounded-md px-1.5 hover:bg-accent has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ring",
        dropdown: "absolute inset-0 cursor-pointer opacity-0",
        nav: "absolute inset-x-0 top-0 flex h-8 items-center justify-between",
        button_previous: navButton,
        button_next: navButton,
        month_grid: "w-full border-collapse",
        weekdays: "flex",
        weekday: "w-9 text-center text-xs font-medium text-muted-foreground",
        week: "mt-1 flex w-full",
        day: "relative size-9 p-0 text-center",
        day_button: cn(
          "inline-flex size-9 items-center justify-center rounded-full text-sm tabular-nums text-foreground",
          "transition-colors duration-fast ease-(--ease-out) hover:bg-accent",
          focusRing,
          "disabled:pointer-events-none",
        ),
        range_start: "rounded-s-full bg-(--option-track) shadow-(--option-track-edge)",
        range_middle: "bg-(--option-track) shadow-(--option-track-edge)",
        range_end: "rounded-e-full bg-(--option-track) shadow-(--option-track-edge)",
        outside: "text-muted-foreground",
        disabled: "opacity-40",
        hidden: "invisible",
        week_number: "w-9 text-xs text-muted-foreground",
        footer: "pt-3 text-sm text-muted-foreground",
        ...classNames,
      }}
      components={{
        Chevron: CalendarChevron,
        DayButton: CalendarDayButton,
        ...components,
      }}
      {...props}
    />
  );
}
Calendar.displayName = "Calendar";

export { Calendar };
